"use client";

import { useState, useEffect } from "react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, Plus, Edit3, Trash2, Eye, Calendar, FileText, 
  CheckCircle, Image as ImageIcon, X, UploadCloud, ChevronLeft, ChevronRight
} from "lucide-react";
import TourGuide from "@/components/TourGuide";
import { createBerita, deleteBerita } from "@/lib/actions";

export default function BeritaClient({ initialPosts }: { initialPosts: any[] }) {
  const [posts, setPosts] = useState(initialPosts);
  const [filterStatus, setFilterStatus] = useState("all"); 
  const [searchQuery, setSearchQuery] = useState("");
  const [isEditorOpen, setIsEditorOpen] = useState(false); 
  const [isClient, setIsClient] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => { setIsClient(true); }, []);

  // Filter Logic
  const filteredPosts = posts.filter((post) => {
    const status = post.status === 'PUBLISHED' ? 'published' : 'draft';
    const matchStatus = filterStatus === "all" ? true : status === filterStatus;
    const matchSearch = post.judul.toLowerCase().includes(searchQuery.toLowerCase());
    return matchStatus && matchSearch;
  });

  const totalViews = posts.reduce((acc, curr) => acc + curr.views, 0);
  const totalPublished = posts.filter(p => p.status === 'PUBLISHED').length;

  // Handle Hapus
  const handleDelete = async (id: number) => {
    if(confirm("Hapus berita ini secara permanen?")) {
      setPosts(posts.filter(p => p.id !== id)); // Hapus di UI dulu biar cepat
      await deleteBerita(id); // Hapus di DB
    }
  };

  // Handle Submit Berita Baru
  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    
    const formData = new FormData(e.currentTarget);
    await createBerita(formData);
    
    setIsSubmitting(false);
    setIsEditorOpen(false);
    alert("Berita Berhasil Diterbitkan! 🎉");
    window.location.reload(); // Refresh biar data baru muncul
  };

  const beritaTourSteps = [
    { target: '.tour-berita-header', content: 'Dapur redaksi sekolah.', disableBeacon: true },
    { target: '.tour-create-btn', content: 'Klik untuk menulis berita baru.' },
    { target: '.tour-stats-cards', content: 'Statistik pembaca artikel.' },
  ];

  return (
    <div className="relative h-full flex flex-col min-h-screen font-sans">
      
      {/* HEADER & STATS */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-8">
        <div>
           <div className="flex items-center gap-4">
               <h1 className="text-3xl font-bold font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-3 tour-berita-header">
                 Kelola Berita <span className="text-2xl p-2 bg-purple-100 dark:bg-purple-900/30 rounded-full">📰</span>
               </h1>
               {isClient && <TourGuide steps={beritaTourSteps} />}
           </div>
           <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">
             Buat, edit, dan pantau performa artikel sekolah.
           </p>
        </div>
        <button 
          onClick={() => setIsEditorOpen(true)}
          className="tour-create-btn px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-600/30 flex items-center gap-2 transition-transform active:scale-95"
        >
           <Plus size={20} /> Tulis Berita Baru
        </button>
      </div>

      {/* STATS CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8 tour-stats-cards">
         <div className="p-5 rounded-2xl bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 shadow-sm flex items-center gap-4">
            <div className="p-3 bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 rounded-xl"><FileText size={24} /></div>
            <div>
               <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Total Artikel</p>
               <p className="text-2xl font-black text-slate-900 dark:text-white">{posts.length}</p>
            </div>
         </div>
         <div className="p-5 rounded-2xl bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 shadow-sm flex items-center gap-4">
            <div className="p-3 bg-green-100 dark:bg-green-500/20 text-green-600 dark:text-green-400 rounded-xl"><CheckCircle size={24} /></div>
            <div>
               <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Terbit</p>
               <p className="text-2xl font-black text-slate-900 dark:text-white">{totalPublished}</p>
            </div>
         </div>
         <div className="p-5 rounded-2xl bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 shadow-sm flex items-center gap-4">
            <div className="p-3 bg-purple-100 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400 rounded-xl"><Eye size={24} /></div>
            <div>
               <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Total Pembaca</p>
               <p className="text-2xl font-black text-slate-900 dark:text-white">{totalViews.toLocaleString('id-ID')}</p>
            </div>
         </div>
      </div>

      {/* FILTER & LIST (Sama seperti sebelumnya, disederhanakan) */}
      <div className="flex-1 space-y-4 pb-8">
         <AnimatePresence>
            {filteredPosts.map((post, index) => (
               <motion.div
                 key={post.id}
                 initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }}
                 className="group flex flex-col md:flex-row items-center gap-6 p-4 bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 rounded-3xl hover:border-blue-400 transition-all"
               >
                  <div className="relative w-full md:w-32 h-20 rounded-2xl overflow-hidden flex-shrink-0 bg-slate-200">
                     <Image src={post.gambar || "https://source.unsplash.com/random"} alt={post.judul} fill className="object-cover" />
                  </div>
                  <div className="flex-1 w-full text-center md:text-left">
                     <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1 line-clamp-1">{post.judul}</h3>
                     <div className="flex items-center justify-center md:justify-start gap-4 text-xs text-slate-500">
                        <span className="flex items-center gap-1"><Calendar size={12}/> {new Date(post.createdAt).toLocaleDateString("id-ID", {
  day: "numeric", 
  month: "short", 
  year: "numeric"
})}</span>
                        <span className="flex items-center gap-1"><Eye size={12}/> {post.views} Views</span>
                     </div>
                  </div>
                  <button onClick={() => handleDelete(post.id)} className="p-2 bg-slate-100 hover:bg-red-600 hover:text-white rounded-lg transition-colors"><Trash2 size={18} /></button>
               </motion.div>
            ))}
         </AnimatePresence>
      </div>

      {/* EDITOR MODAL (FORM ASLI) */}
      <AnimatePresence>
         {isEditorOpen && (
            <motion.div 
               initial={{ opacity: 0, y: "100%" }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: "100%" }}
               className="fixed inset-0 z-[60] bg-[#F8FAFC] dark:bg-[#020617] flex flex-col"
            >
               <form onSubmit={handleSubmit} className="flex flex-col h-full">
                   {/* Editor Header */}
                   <div className="h-16 px-6 border-b border-slate-200 dark:border-white/10 flex items-center justify-between bg-white dark:bg-[#0a0f1e]">
                      <div className="flex items-center gap-4">
                         <button type="button" onClick={() => setIsEditorOpen(false)} className="p-2 hover:bg-slate-100 rounded-full"><X size={24} /></button>
                         <h2 className="text-lg font-bold">Tulis Berita Baru</h2>
                      </div>
                      <button disabled={isSubmitting} className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold flex items-center gap-2">
                         {isSubmitting ? "Menyimpan..." : <><UploadCloud size={18} /> Publish</>}
                      </button>
                   </div>

                   {/* Editor Content */}
                   <div className="flex-1 overflow-y-auto p-10 max-w-4xl mx-auto w-full space-y-6">
                      <input 
                         name="judul"
                         type="text" 
                         placeholder="Judul Artikel..." 
                         className="w-full bg-transparent text-4xl font-black text-slate-900 dark:text-white outline-none placeholder:text-slate-300"
                         required
                      />
                      
                      <div className="flex gap-4">
                         <select name="kategori" className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-sm font-bold">
                            <option value="Umum">Umum</option>
                            <option value="Prestasi">Prestasi</option>
                            <option value="Event">Event</option>
                         </select>
                      </div>

                      <textarea 
                         name="konten"
                         className="w-full h-[500px] text-lg text-slate-600 dark:text-slate-300 outline-none bg-transparent resize-none" 
                         placeholder="Mulai menulis cerita inspiratif di sini..."
                         required
                      />
                   </div>
               </form>
            </motion.div>
         )}
      </AnimatePresence>

    </div>
  );
}